// Metadata inspection only. Never interprets or executes printer commands.
export const HEADER_LIMIT = 1024 * 1024;

export function parseEstimatedTime(value) {
  if (typeof value !== 'string') return null;
  const match = value.trim().match(/^(?:(\d+)d\s*)?(?:(\d+)h\s*)?(?:(\d+)m\s*)?(?:(\d+)s)?$/);
  if (!match || !match.slice(1).some(Boolean)) return null;
  const seconds = Number(match[1] || 0) * 86400 + Number(match[2] || 0) * 3600 + Number(match[3] || 0) * 60 + Number(match[4] || 0);
  return Number.isSafeInteger(seconds) && seconds > 0 && seconds <= 31536000 ? seconds : null;
}
export function readTimeEstimate(text, filename = '') {
  if (typeof text !== 'string' || text.length > HEADER_LIMIT) throw new Error('The metadata must fit within the first 1 MiB.');
  const end = text.indexOf('; CONFIG_BLOCK_END');
  if (end < 0) throw new Error('A complete Flash Studio configuration header is required.');
  const header = text.slice(0, end);
  const generatedBy = header.match(/^; generated by (Flash Studio [^\r\n]+)$/m)?.[1];
  const estimates = [...header.matchAll(/^; estimated printing time \(normal mode\)\s*=\s*([^\r\n]+)$/gm)];
  const seconds = estimates.length === 1 ? parseEstimatedTime(estimates[0][1]) : null;
  if (!generatedBy || seconds === null) throw new Error('A unique, valid Flash Studio print-time estimate was not found.');
  return { seconds, filename, generatedBy };
}

function numeric(value) {
  if (typeof value !== 'string' || !/^\d+(?:\.\d+)?$/.test(value.trim())) return null;
  const result = Number(value);
  return Number.isFinite(result) ? result : null;
}
function list(value, delimiter = ',') { return value?.split(delimiter).map(v => v.trim().replace(/^"(.*)"$/, '$1')) || []; }

export function inspectGcode(text, filename = '') {
  if (typeof text !== 'string' || text.length > HEADER_LIMIT) throw new Error('The metadata must fit within the first 1 MiB.');
  const end = text.indexOf('; CONFIG_BLOCK_END');
  if (end < 0 || !/^; generated by Flash Studio /m.test(text)) throw new Error('This inspector needs a Flash Studio G-code export with a complete configuration header. Sliced 3MF import is not supported yet.');
  const header = text.slice(0, end);
  const values = new Map();
  const rows = [];
  const issues = [];
  const warnings = [];
  const wanted = new Set(['filament used [g]', 'total filament used [g]', 'filament_colour', 'filament_type', 'filament_vendor', 'filament_settings_id', 'filament_diameter', 'nozzle_diameter', 'printer_model', 'printer_settings_id', 'print_settings_id', 'layer_height', 'estimated printing time (normal mode)']);
  for (const line of header.split(/\r?\n/)) {
    const entry = line.match(/^; ([^=]+?)\s*=\s*(.*)$/);
    if (entry && wanted.has(entry[1].trim())) {
      const key = entry[1].trim();
      if (values.has(key)) issues.push(`Duplicate ${key} metadata.`);
      values.set(key, entry[2]);
    }
    if (/^; <filament\s/.test(line)) {
      const attributes = Object.fromEntries([...line.matchAll(/([a-z_]+)="([^"\r\n]*)"/g)].map(m => [m[1], m[2]]));
      rows.push(attributes);
    }
  }
  if (!rows.length || rows.length > 16) throw new Error('No supported per-filament records were found.');
  const weights = list(values.get('filament used [g]')).map(numeric);
  const colors = list(values.get('filament_colour'), ';');
  const types = list(values.get('filament_type'), ';');
  const profiles = list(values.get('filament_settings_id'), ';');
  const vendors = list(values.get('filament_vendor'), ';');
  const diameters = list(values.get('filament_diameter')).map(numeric);
  const nozzles = list(values.get('nozzle_diameter')).map(numeric);
  for (const [label, array] of [['gram estimates', weights], ['colors', colors], ['materials', types], ['filament diameters', diameters], ['nozzle diameters', nozzles]]) {
    if (array.length !== rows.length) issues.push(`The number of ${label} does not match the filament records.`);
  }
  const channels = rows.map((row, index) => {
    const id = numeric(row.id);
    if (id !== index + 1) issues.push('Filament IDs are not in the expected consecutive order; tool mapping cannot be verified.');
    const color = /^#[0-9a-f]{6}$/i.test(row.color || '') ? row.color.toUpperCase() : null;
    const material = row.type || null;
    const summaryGrams = weights[index] ?? null;
    const recordGrams = numeric(row.used_g);
    if (!color || !material || summaryGrams === null || recordGrams === null || !(diameters[index] > 0) || !(nozzles[index] > 0)) issues.push(`Channel ${index + 1} has missing or invalid requirements.`);
    if (color !== colors[index]?.toUpperCase() || material !== types[index]) issues.push(`Channel ${index + 1} has conflicting material or color metadata.`);
    if (summaryGrams !== null && recordGrams !== null && Math.abs(summaryGrams - recordGrams) > .011) warnings.push(`Channel ${index + 1}: summary ${summaryGrams.toFixed(2)} g versus filament record ${recordGrams.toFixed(2)} g.`);
    return { channel: index + 1, material, color, profile: profiles[index] || null, vendor: vendors[index] || null, diameter: diameters[index] ?? null, nozzle: nozzles[index] ?? null, summaryGrams, recordGrams,
      planningGrams: summaryGrams !== null && recordGrams !== null ? Math.max(summaryGrams, recordGrams) : null };
  });
  const totalGrams = numeric(values.get('total filament used [g]'));
  const summaryTotal = weights.length === rows.length && weights.every(v => v !== null) ? Math.round(weights.reduce((sum, n) => sum + n, 0) * 100) / 100 : null;
  const recordTotal = channels.every(c => c.recordGrams !== null) ? Math.round(channels.reduce((sum, c) => sum + c.recordGrams, 0) * 100) / 100 : null;
  if (totalGrams === null || summaryTotal === null || Math.abs(totalGrams - summaryTotal) > .011 * rows.length) issues.push('The declared total does not match the per-channel summary.');
  const printer = values.get('printer_model') || null;
  if (!printer) issues.push('The target printer profile is missing.');
  const generatedBy = header.match(/^; generated by (.+)$/m)?.[1] || null;
  const layerMatch = header.match(/^; total layer number:\s*(\d+)/m);
  const duplicateColors = channels.some((c, index) => c.color && channels.slice(0, index).some(other => other.color === c.color));
  if (duplicateColors) warnings.push('Some channels use the same color. Keep each channel separate until its physical spool and tool mapping are confirmed.');
  return { filename, generatedBy, printer, printerProfile: values.get('printer_settings_id') || null, printProfile: values.get('print_settings_id') || null,
    layerHeight: numeric(values.get('layer_height')), layers: layerMatch ? Number(layerMatch[1]) : null,
    estimatedTime: values.get('estimated printing time (normal mode)') || null, estimatedTimeSeconds: parseEstimatedTime(values.get('estimated printing time (normal mode)')), channels, totalGrams, summaryTotal, recordTotal,
    metadataComplete: issues.length === 0, issues: [...new Set(issues)], warnings,
    inventoryVerified: false, readyToPrint: false,
    limitation: 'Metadata inspection only. Loaded spools, measured quantities, purge accounting, reserve, and printer submission are not verified.' };
}
